insert into public.fc_era_catalog(id,from_year,to_year) values ('1960s',1960,1969),('1970s-a',1970,1974),('1970s-b',1975,1979),('1980s-a',1980,1984),('1980s-b',1985,1989),('1990s-a',1990,1994),('1990s-b',1995,1999),('2000s-a',2000,2004),('2000s-b',2005,2009),('2010s-a',2010,2014),('2010s-b',2015,2019),('2020s',2020,2024) on conflict(id) do update set from_year=excluded.from_year,to_year=excluded.to_year;
insert into public.fc_chemistry_pairs(id,left_identity,right_identity,bonus) values ('madrid-wings','cristiano-ronaldo','gareth-bale',2),('madrid-finishing','cristiano-ronaldo','karim-benzema',2),('bbc-partners','gareth-bale','karim-benzema',2),('madrid-control','luka-modric','toni-kroos',2),('barca-control','xavi','andres-iniesta',2),('barca-right','lionel-messi','dani-alves',2),('brazil-1970','pele','jairzinho',2),('total-football','johan-cruyff','johan-neeskens',2),('argentina-1986','diego-maradona','jorge-burruchaga',2),('liverpool-wings','mohamed-salah','sadio-mane',2),('argentina-2022','lionel-messi','julian-alvarez',2),('france-midfield','ngolo-kante','paul-pogba',2) on conflict(id) do update set left_identity=excluded.left_identity,right_identity=excluded.right_identity,bonus=excluded.bonus;
insert into public.fc_chemistry_trios(id,identities,bonus_mode,bonus) values ('bbc',ARRAY['cristiano-ronaldo','gareth-bale','karim-benzema'],'flat',5),('msn',ARRAY['lionel-messi','neymar','luis-suarez'],'flat',5),('dutch-three',ARRAY['ruud-gullit','marco-van-basten','frank-rijkaard'],'flat',5) on conflict(id) do update set identities=excluded.identities,bonus_mode=excluded.bonus_mode,bonus=excluded.bonus;
   insert into fc_rooms(code,mode,owner,rules_version) values(c,p_mode,auth.uid(),p_rules) on conflict do nothing returning * into r;
  insert into fc_members(room_code,user_id,seat) values(r.code,auth.uid(),n);
  insert into fc_player_locks(room_code,player_key,user_id) values(p_code,c.player_key,auth.uid()) on conflict do nothing;
